"""Offline, self-contained reporting view for synthetic private-markets analysis."""

from __future__ import annotations

from html import escape
import json
import math
from string import Template
from typing import Any


def _json_safe(value: Any) -> Any:
    """Keep embedded data valid JSON even when an upstream metric is nonfinite."""
    if isinstance(value, float) and not math.isfinite(value):
        return None
    if isinstance(value, dict):
        return {str(key): _json_safe(item) for key, item in value.items()}
    if isinstance(value, (list, tuple)):
        return [_json_safe(item) for item in value]
    return value


def render_report(payload: dict) -> str:
    """Render a report without remote assets, services, or third-party libraries.

    Values are cents unless the payload field is a multiple or annualized rate.
    Payload text is escaped in HTML and rendered using textContent in JavaScript.
    The embedded JSON escapes HTML delimiters to prevent script-tag termination.
    """
    serialized = json.dumps(_json_safe(payload), ensure_ascii=True, allow_nan=False)
    serialized = (serialized.replace("<", "\\u003c")
                  .replace(">", "\\u003e")
                  .replace("&", "\\u0026"))
    rendered = _REPORT.substitute(
        payload=serialized,
        asof=escape(str(payload.get("asof", "Not supplied")), quote=True),
        known_at=escape(str(payload.get("known_at", "Not supplied")), quote=True),
        data_kind=escape(str(payload.get("data_kind", "SYNTHETIC")), quote=True),
        status=escape(str(payload.get("status", "REVIEW_REQUIRED")), quote=True),
    )
    from .advanced_report import render_advanced_report
    if payload.get('advanced'):
        rendered = rendered.replace('</nav>', '<a href="#partnership">Investor accounts</a><a href="#waterfalls">Carry &amp; clawback</a><a href="#return-diagnostics">Return diagnostics</a><a href="#public-research">Public research</a></nav>')
        rendered = rendered.replace('No public fund data is used in these calculations.', 'Comparison funds and partnership use synthetic records. Public disclosure research is shown separately.')
        footer_start = rendered.index('<div class="footer">')
        footer_end = rendered.index('</div>', footer_start) + len('</div>')
        footer = rendered[footer_start:footer_end]
        rendered = rendered[:footer_start] + rendered[footer_end:]
        return rendered.replace('</main>', render_advanced_report(payload) + footer + '</main>')
    return rendered


